BEGIN;
CREATE TABLE knowledge_sources(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),ai_agent_id uuid NOT NULL REFERENCES ai_agents(id),source_type text NOT NULL CHECK(source_type IN('script','url','document')),source_uri text,title text,authorization_confirmed_at timestamptz NOT NULL,state text NOT NULL DEFAULT 'queued' CHECK(state IN('queued','fetching','review','published','failed','retired')),refresh_hours integer CHECK(refresh_hours BETWEEN 1 AND 720),content_sha256 text,last_error text,last_fetched_at timestamptz,next_fetch_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE knowledge_chunks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),source_id uuid NOT NULL REFERENCES knowledge_sources(id) ON DELETE CASCADE,ordinal integer NOT NULL,content text NOT NULL,search_vector tsvector GENERATED ALWAYS AS(to_tsvector('simple',content)) STORED,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(source_id,ordinal));
CREATE INDEX knowledge_chunks_search_idx ON knowledge_chunks USING gin(search_vector);CREATE INDEX knowledge_sources_queue_idx ON knowledge_sources(state,next_fetch_at,created_at);
ALTER TABLE knowledge_sources ENABLE ROW LEVEL SECURITY;ALTER TABLE knowledge_sources FORCE ROW LEVEL SECURITY;ALTER TABLE knowledge_chunks ENABLE ROW LEVEL SECURITY;ALTER TABLE knowledge_chunks FORCE ROW LEVEL SECURITY;CREATE POLICY knowledge_sources_isolation ON knowledge_sources USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);CREATE POLICY knowledge_chunks_isolation ON knowledge_chunks USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);
COMMIT;
